// Challenge mode UI: case picker, live banner (timer, goal, stability), result card with score and best times.
const CHBEST=(()=>{try{return JSON.parse(localStorage.getItem('traumaLabBest')||'{}')||{};}catch(e){return {};}})();
function chSaveBest(){try{localStorage.setItem('traumaLabBest',JSON.stringify(CHBEST));}catch(e){}}
const fmtClock=s=>{s=Math.max(0,s);const m=Math.floor(s/60),r=Math.floor(s%60);return m+':'+(r<10?'0':'')+r;};
const CHKIND={trauma:'Trauma',arrest:'Heart',surgery:'Surgery',medical:'Drugs & poisons'};
(()=>{const d=document.createElement('div');d.id='chal';d.hidden=true;d.setAttribute('role','dialog');d.setAttribute('aria-label','Challenge');document.body.appendChild(d);
  const b=document.createElement('div');b.id='chbar';b.hidden=true;document.body.appendChild(b);})();
// during a challenge only medicine and your hands are allowed
function chAllowed(id){if(CH_BANNED.has(id))return false;const t=TOOL[id];if(!t)return false;const top=TOPOF(t.cat);return top==='med'||top==='hand';}
function openChallenge(){closeMenu();const d=$('chal');
  let h='<div class="chhead"><h3>Keep him alive</h3><button id="chClose">Close</button></div><p class="chint">A real emergency starts. Use only the Medicine tab. Keep his systolic pressure above 60 mmHg and get him stable for 15 s.</p>';
  h+='<button class="chcase chrand" data-c="random"><b>Random case</b><em>Any of the emergencies below</em></button>';
  for(const k of ['trauma','arrest','surgery','medical']){const L=CASES.filter(c=>c.kind===k);if(!L.length)continue;h+=`<h4>${CHKIND[k]}</h4>`;
    for(const c of L){const bst=CHBEST[c.id];h+=`<button class="chcase" data-c="${c.id}"><b>${c.name}</b><em>${c.who}${bst?` · best ${fmtClock(bst.t)} · ${bst.score} pts`:''}</em></button>`;}}
  d.innerHTML=h;d.hidden=false;
  $('chClose').onclick=()=>{d.hidden=true;};
  d.querySelectorAll('.chcase').forEach(b=>b.onclick=()=>{d.hidden=true;runChallenge(b.dataset.c);});}
function runChallenge(id){const C=chStart(id);
  if(OPT.god){OPT.god=false;}
  if(CH.prevMap==null)CH.prevMap=MAP;if(MAP!=='room'){MAP='room';layout();CAM.side.z=fitZ();CAM.side.px=0;CAM.side.py=0;}
  setScene(C.scene,true);reset();if(view!=='side')setView('side');
  if(TOOL[tool]&&!chAllowed(tool))selectTool('bandage');
  chBegin();chUI(true);}
function endChallenge(){document.body.classList.remove('chon');if(!CH)return;const ps=CH.prevScene,pm=CH.prevMap;if(pm&&pm!==MAP){MAP=pm;layout();CAM.side.z=fitZ();CAM.side.px=0;CAM.side.py=0;}V.patient=false;CH.on=false;CH=null;$('chbar').hidden=true;if(typeof layout==='function')layout();$('chal').hidden=true;setScene(ps,true);}
function chUI(force){const b=$('chbar');document.body.classList.toggle('chon',!!(CH&&CH.on));if(!CH||!CH.on){b.hidden=true;return;}
  const C=CH.c;
  if(force||b.dataset.c!==C.id){b.dataset.c=C.id;
    b.innerHTML=`<div class="chl"><b>${C.name}</b><span>${C.who}</span></div><div class="cht" id="chT">0:00</div><div class="chg"><span id="chG">Stabilise him</span><i class="chbarw"><i id="chP"></i></i></div><button id="chTip" title="What to do">Tip</button><button id="chQuit">Give up</button>`;
    $('chQuit').onclick=()=>{if(CH&&!CH.done){CH.done=true;CH.result={win:false,why:'You gave up',t:CH.el};}chResult();};
    $('chTip').onclick=()=>{if(CH)log('Tip · '+CH.c.tip,'info');};}
  b.hidden=false;b.style.top=($('hud').offsetHeight+6)+'px';$('viewctl').style.top=($('hud').offsetHeight+6+b.offsetHeight+8)+'px';
  $('chT').textContent=fmtClock(CH.el);$('chP').style.width=Math.round(clamp(CH.stable/CH_STABLE,0,1)*100)+'%';
  $('chG').innerHTML=CH.done?'':CH.low>0?`<i class="bad">BP under 60 · ${Math.max(0,6-CH.low).toFixed(0)} s</i>`:CH.hyp>0?`<i class="bad">SpO₂ under 50% · ${Math.max(0,30-CH.hyp).toFixed(0)} s</i>`:CH.stable>0?'Stable · hold it…':'Stabilise him';
  if(CH.done&&!CH.shown)chResult();}
function chResult(){if(!CH)return;CH.shown=true;const r=CH.result||{win:false,why:'',t:CH.el},C=CH.c,d=$('chal');let rec='';
  if(r.win){const b=CHBEST[C.id];if(!b||r.score>b.score||(r.score===b.score&&r.t<b.t)){CHBEST[C.id]={t:r.t,score:r.score};chSaveBest();rec='<p class="chrec">New best!</p>';}}
  const b=CHBEST[C.id];
  d.innerHTML=`<div class="chres ${r.win?'win':'lose'}"><h3>${r.win?'Stabilised':'Lost him'}</h3><p class="chsub">${C.name} · ${C.who}</p>
    ${r.win?`<div class="chnums"><div><b>${fmtClock(r.t)}</b><span>to stabilise</span></div><div><b>${r.score}</b><span>score</span></div><div><b>${Math.round(V.blood)}</b><span>mL blood left</span></div></div>`:`<p class="chwhy">${r.why}</p><p class="chsub">Survived ${fmtClock(r.t)}</p>`}
    ${rec}${b?`<p class="chsub">Best: ${fmtClock(b.t)} · ${b.score} pts</p>`:''}<p class="chtip"><b>In real life:</b> ${C.tip}</p>
    <div class="chbtns"><button id="chRetry">Retry</button><button id="chNew">Other case</button><button id="chExit">Back to sandbox</button></div></div>`;
  d.hidden=false;
  $('chRetry').onclick=()=>{const id=C.id;d.hidden=true;endChallenge();runChallenge(id);};
  $('chNew').onclick=()=>{endChallenge();openChallenge();};
  $('chExit').onclick=()=>{d.hidden=true;endChallenge();};}
function setScene(id,quiet){if(!SCENES[id])id='lab';OPT.scene=id;saveOpt();bgKey='';if(!quiet)log('Scene · '+SCENES[id].name,'info');}

// ---------- main menu: choose Sandbox or Keep him alive ----------
(()=>{const d=document.createElement('div');d.id='home';d.setAttribute('role','dialog');d.setAttribute('aria-label','Main menu');document.body.appendChild(d);})();
const PUBLIC_VER=()=>{try{return fmtVer(GAME_VERSION);}catch(e){return "v1.19";}};
const DISCORD_URL="https://discord.gg/6BCWDfuMgm";
const INSTAGRAM_URL="https://www.instagram.com/traumalab.game/";
const TIKTOK_URL="https://www.tiktok.com/@traumalabgame";
const ITCH_URL="https://traumalab.itch.io/trauma-lab";
const NEWSHOTS=[{"src": "data:image/jpeg;base64,", "t": "Story mode", "d": "Wake up in a cell. Get out of the lab"}, {"src": "data:image/jpeg;base64,", "t": "Story mode", "d": "Guards, cover and real damage"}, {"src": "data:image/jpeg;base64,", "t": "Story mode", "d": "Run, crouch, take cover, treat your own wounds"}];
function openHome(){
  if(CH&&CH.on){if(!CH.done){CH.done=true;CH.result={win:false,why:'You left the challenge',t:CH.el};}endChallenge();}
  closeMenu();if(typeof opfClose==='function')opfClose(true);if(typeof oplClose==='function')oplClose(true);$('chal').hidden=true;const d=$('home'),sp=document.querySelector('#splash img');
  const won=CASES.filter(c=>CHBEST[c.id]).length;
  d.innerHTML=`<div class="hm">
    <div class="hbar">${sp?`<img class="hlogo" src="${sp.src}" alt="Trauma Lab">`:'<h1>TRAUMA LAB</h1>'}<div class="hlang" data-noi18n role="group" aria-label="Language / Язык"><button data-lang="en" aria-pressed="${TL_LANG!=='ru'}" title="English"><svg viewBox="0 0 60 40" aria-hidden="true"><defs><clipPath id="flUS"><path d="M0 0H60L0 40Z"/></clipPath><clipPath id="flUK"><path d="M60 0V40H0Z"/></clipPath></defs><g clip-path="url(#flUS)"><rect width="60" height="40" fill="#b22234"/><path d="M0 4.6H60M0 10.8H60M0 16.9H60M0 23.1H60M0 29.2H60M0 35.4H60" stroke="#fff" stroke-width="3.1"/><rect width="26" height="21.5" fill="#3c3b6e"/><g fill="#fff"><circle cx="5" cy="4.5" r="1.2"/><circle cx="12" cy="4.5" r="1.2"/><circle cx="19" cy="4.5" r="1.2"/><circle cx="8.5" cy="9.5" r="1.2"/><circle cx="15.5" cy="9.5" r="1.2"/><circle cx="5" cy="14.5" r="1.2"/><circle cx="12" cy="14.5" r="1.2"/><circle cx="19" cy="14.5" r="1.2"/></g></g><g clip-path="url(#flUK)"><rect width="60" height="40" fill="#012169"/><path d="M0 0L60 40M60 0L0 40" stroke="#fff" stroke-width="8"/><path d="M0 0L60 40M60 0L0 40" stroke="#c8102e" stroke-width="3"/><path d="M30 0V40M0 20H60" stroke="#fff" stroke-width="12"/><path d="M30 0V40M0 20H60" stroke="#c8102e" stroke-width="7"/></g><path d="M60 0L0 40" stroke="rgba(0,0,0,.35)" stroke-width="1"/></svg><span>English</span></button><button data-lang="ru" aria-pressed="${TL_LANG==='ru'}" title="Русский"><svg viewBox="0 0 60 40" aria-hidden="true"><rect width="60" height="13.4" fill="#fff"/><rect y="13.3" width="60" height="13.4" fill="#0039a6"/><rect y="26.6" width="60" height="13.4" fill="#d52b1e"/></svg><span>Русский</span></button></div></div>
    <div class="hold" role="note"><b>Free version</b><span>You're playing <i>${PUBLIC_VER()}</i> for free. <i>Story mode</i> and the newest builds go to Discord playtesters and supporters first.</span><div class="hbtns"><a class="hdisc hdisc-s" href="${DISCORD_URL}" target="_blank" rel="noopener"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 5h16v11H9l-5 4z"/><path d="M8 10h.01M12 10h.01M16 10h.01"/></svg>Join the Discord playtest</a><button class="hdisc hdisc-s hsupp" id="hSupp" type="button"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 20s-7-4.4-7-9.6A4 4 0 0 1 12 8a4 4 0 0 1 7 2.4C19 15.6 12 20 12 20z"/></svg>Supporter build</button></div></div>
    <div class="hmodes">
      <button class="hmode" id="hSand"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 20h16M6 20V9l6-5 6 5v11M9 20v-6h6v6"/></svg><b>Sandbox</b><em>Free play · every weapon, tool, chemical and power</em></button>
      <button class="hmode hcm" id="hAlive"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 21s-7-4.5-7-10a4 4 0 0 1 7-2.6A4 4 0 0 1 19 11c0 5.5-7 10-7 10zM6 12h3l1.5-3 2 6 1.5-3H18"/></svg><b>Keep him alive</b><em>${CASES.length} real emergencies · medicine only${won?` · ${won}/${CASES.length} stabilised`:''}</em></button>
      <button class="hmode hstory hlock" id="hStory"><i class="hbadge">Locked</i><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M13 4a2 2 0 1 1-4 0 2 2 0 0 1 4 0zM10 8l-3 5h3l-1 7M11 8l3 4 3 1M10 13l3 3v4"/></svg><b>Story <i>prototype</i></b><em>Playtesters and supporters only · tap to see how to get it</em></button>
    </div>
    <div class="hnext"><h2>Story mode</h2><p>Escape the lab as the test subject. It's in testing with Discord playtesters and supporters. Tap a picture to see it bigger.</p>
      <div class="hshots">${NEWSHOTS.map((h,i)=>`<figure class="hshot" data-i="${i}" tabindex="0" role="button" aria-label="${h.t}: ${h.d}"><img src="${h.src}" alt="${h.t}: ${h.d}" loading="lazy"><figcaption><b>${h.t}</b>${h.d}</figcaption></figure>`).join('')}</div>
      <div class="hbtns"><a class="hdisc" href="${DISCORD_URL}" target="_blank" rel="noopener"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 5h16v11H9l-5 4z"/><path d="M8 10h.01M12 10h.01M16 10h.01"/></svg><span>Join the Discord playtest<small>Free · testers are picked in waves</small></span></a><button class="hdisc hsupp" id="hSupp2" type="button"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 20s-7-4.4-7-9.6A4 4 0 0 1 12 8a4 4 0 0 1 7 2.4C19 15.6 12 20 12 20z"/></svg><span>Supporter build<small>Story mode + newest builds first</small></span></button></div>
    </div>
    <div class="hsurg"><span>Surgery mode</span><div class="oseg" role="group" aria-label="Surgery mode"><button data-v="simple" aria-pressed="${OPT.surg!=='complex'}">Simple</button><button data-v="complex" aria-pressed="${OPT.surg==='complex'}">Complex</button></div><em id="hSurgD">${OPT.surg==='complex'?'You cut, clamp, sew and inject yourself':'Tap and it happens'}</em></div>
    <div class="hfoot"><button id="hHelp">How to play</button><button id="hOpt">Options</button><button id="hNews">What's new</button></div>
    <p class="hcopy">${COPYRIGHT}<br>${NOTICE}</p></div>`;
  d.hidden=false;document.body.classList.add('homeon');
  {let z=$('hzoom');if(!z){z=document.createElement('div');z.id='hzoom';z.hidden=true;z.setAttribute('role','dialog');z.setAttribute('aria-label','Screenshot');z.onclick=()=>{z.hidden=true;};document.body.appendChild(z);}
   d.querySelectorAll('.hshot').forEach(f=>{const open=()=>{const h=NEWSHOTS[+f.dataset.i];z.innerHTML=`<div><img src="${h.src}" alt=""><p><b style="color:var(--accent)">${h.t}</b> · ${h.d}</p></div>`;z.hidden=false;};f.onclick=open;f.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open();}};});}
  d.querySelectorAll('.hsurg button').forEach(b=>b.onclick=()=>{OPT.surg=b.dataset.v;saveOpt();d.querySelectorAll('.hsurg button').forEach(q=>q.setAttribute('aria-pressed',q===b));$('hSurgD').textContent=OPT.surg==='complex'?'You cut, clamp, sew and inject yourself':'Tap and it happens';});
  $('hSand').onclick=()=>{closeHome();if(OPT.scene!=='lab'||V.dead){setScene(OPT.scene||'lab',true);}log('Sandbox · pick a category below','info');openCoach();};
  $('hAlive').onclick=()=>{closeHome();openChallenge();};
  $('hStory').onclick=()=>openSupporter();
  [$('hSupp'),$('hSupp2')].forEach(b=>b&&(b.onclick=()=>openSupporter()));
  $('hHelp').onclick=()=>{closeHome();openHelp();};
  $('hOpt').onclick=()=>{closeHome();$('bOpt').click();};
  $('hNews').onclick=()=>{closeHome();openNews();};
  d.querySelectorAll('.hlang button').forEach(b=>b.onclick=()=>{if(b.dataset.lang===TL_LANG)return;try{localStorage.setItem('traumaLabLang',b.dataset.lang);}catch(e){}location.reload();});}
function closeHome(){$('home').hidden=true;document.body.classList.remove('homeon');}
$('bHome').onclick=()=>openHome();
if(!window.__noNews)openHome();else $('home').hidden=true;
